// Ref is the handle of the value of an instance of a class unit (T-5), which the release function frees when the Go
// runtime finds the Ref unreachable. It keeps the release function, a pointer, so that the runtime allocates it on its
// own: an object without a pointer shares a block with other small objects, and its cleanup runs only when every
// object of the block is unreachable.
type Ref struct {
	handle  uint64
	release func(uint64)
}

// NewRef holds a handle that a call gave and releases it with release.
func NewRef(handle uint64, release func(uint64)) *Ref {
	ref := &Ref{handle: handle, release: release}
	runtime.AddCleanup(ref, release, handle)
	return ref
}

// Handle is the handle of the value.
func (r *Ref) Handle() uint64 { return r.handle }

// Callback runs a member of a Go callback for the core (U-3): the decoded arguments in, the encoded result out.
type Callback func(call *Call, member uint32, dec *Reader, enc *Writer) error

// held is a Go value whose children the core may ask for (U-7), with the keys of a map in their order; a
// *KeyedMap[any] is its entries in their order. An instance of
// a value class is the read of its in case, the read member of a class of another repository (GN-6x) or the kept
// value of a class without core_type (GN-6af), and an instance of a class of an owner that iterates keys and values
// is the entries of that iteration (GN-6x).
type held struct {
	value   reflect.Value
	keys    []reflect.Value
	read    func() (any, error)
	units   func() (any, error)
	coded   bool
	entries [][2]reflect.Value
}

// Call is one call into the static library that runs Go code: the values that the core walks (U-7), the callbacks
// that it runs and the errors that they returned (U-3). The static library names it by its cgo.Handle.
type Call struct {
	handle    cgo.Handle
	held      []held
	callbacks []Callback
	raised    []error
}

// NewCall is a call, which Close ends.
func NewCall() *Call {
	c := &Call{}
	c.handle = cgo.NewHandle(c)
	return c
}

// Close ends the call; the static library names it no more.
func (c *Call) Close() { c.handle.Delete() }

// Callback encodes a callback of the call: the call and its index in it.
func (c *Call) Callback(enc *Writer, callback Callback) {
	c.callbacks = append(c.callbacks, callback)
	enc.Uint(uint64(c.handle))
	enc.Uint(uint64(len(c.callbacks)))
}

// Value encodes a value of a value alias (U-7): the call, through which the core walks it, and its first level.
func (c *Call) Value(enc *Writer, value any) {
	enc.Uint(uint64(c.handle))
	c.describe(enc, reflect.ValueOf(value))
}

// describe encodes one level of a Go value (B-1): 0 nil, 1 a bool, 2 an integer, 3 an integer beyond int64 (a uint64
// or a *big.Int) as its decimal text, 4 a float, 5 a string, 6 a []byte, 7 a slice or an array, 8 a map with its keys in the order of their
// text, 9 a func with the cgo.Handle that a Native deletes (GN-6u), 10 any other value with its type name; a container
// with its handle and length.
func (c *Call) describe(enc *Writer, value reflect.Value) {
	for value.IsValid() && value.Kind() == reflect.Interface {
		value = value.Elem()
	}
	if !value.IsValid() {
		enc.bytes = append(enc.bytes, 0)
		return
	}
	if c.describeClass(enc, value) {
		return
	}
	if value.CanInterface() {
		if number, isBig := value.Interface().(*big.Int); isBig && number != nil {
			if number.IsInt64() {
				enc.bytes = append(enc.bytes, 2)
				enc.Int(number.Int64())
			} else {
				enc.bytes = append(enc.bytes, 3)
				enc.Text(number.String())
			}
			return
		}
	}
	if c.describeOwn(enc, value) {
		return
	}
	switch value.Kind() {
	case reflect.Bool:
		enc.bytes = append(enc.bytes, 1)
		enc.Bool(value.Bool())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		enc.bytes = append(enc.bytes, 2)
		enc.Int(value.Int())
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		if value.Uint() <= math.MaxInt64 {
			enc.bytes = append(enc.bytes, 2)
			enc.Int(int64(value.Uint()))
		} else {
			enc.bytes = append(enc.bytes, 3)
			enc.Text(strconv.FormatUint(value.Uint(), 10))
		}
	case reflect.Float32, reflect.Float64:
		enc.bytes = append(enc.bytes, 4)
		enc.Float(value.Float())
	case reflect.String:
		enc.bytes = append(enc.bytes, 5)
		enc.Text(value.String())
	case reflect.Slice, reflect.Array:
		if value.Kind() == reflect.Slice && value.Type().Elem().Kind() == reflect.Uint8 {
			enc.bytes = append(enc.bytes, 6)
			enc.Bytes(value.Bytes())
			return
		}
		enc.bytes = append(enc.bytes, 7)
		enc.Uint(c.hold(held{value: value}))
		enc.Uint(uint64(value.Len()))
	case reflect.Map:
		keys := value.MapKeys()
		slices.SortFunc(keys, func(a, b reflect.Value) int {
			return strings.Compare(fmt.Sprint(a.Interface()), fmt.Sprint(b.Interface()))
		})
		enc.bytes = append(enc.bytes, 8)
		enc.Uint(c.hold(held{value: value, keys: keys}))
		enc.Uint(uint64(len(keys)))
	case reflect.Func:
		enc.bytes = append(enc.bytes, 9)
		enc.Uint(uint64(cgo.NewHandle(value.Interface())))
	default:
		enc.bytes = append(enc.bytes, 10)
		enc.Text(value.Type().String())
		enc.Uint(c.hold(held{value: value}))
	}
}

func (c *Call) hold(value held) uint64 {
	c.held = append(c.held, value)
	return uint64(len(c.held))
}

// host answers a question of the core about a value: the item of a list (op 0) or the key and the value of the entry
// of a map (op 1), or the content of an instance of a value class (op 2, GN-6x, GN-6af).
func (c *Call) host(op uint32, handle, index uint64) ([]byte, bool) {
	if handle == 0 || handle > uint64(len(c.held)) {
		return nil, false
	}
	held := c.held[handle-1]
	value := held.value
	keys := held.keys
	enc := NewWriter()
	switch {
	case op == 0 && (value.Kind() == reflect.Slice || value.Kind() == reflect.Array) && index < uint64(value.Len()):
		c.describe(enc, value.Index(int(index)))
	case op == 1 && value.Kind() == reflect.Map && index < uint64(len(keys)):
		c.describe(enc, keys[index])
		c.describe(enc, value.MapIndex(keys[index]))
	case op == 1 && index < uint64(len(held.entries)):
		c.describe(enc, held.entries[index][0])
		c.describe(enc, held.entries[index][1])
	case op == 2 && held.read != nil:
		content, err := held.read()
		coded := held.coded
		if err == nil && held.units != nil {
			// B2.89: a text, or a nil pointer for a text with an unpaired surrogate, whose UTF-16 code units the units
			// member gives, so only such a text crosses as a list of integers.
			if text, _ := content.(*string); text != nil {
				content = *text
			} else {
				content, err = held.units()
				coded = true
			}
		}
		if err != nil {
			c.raiseIn(enc, err)
		} else if coded {
			// B2.81: node 13, the UTF-16 code units of a text of the kind text16, which the read member gives as a
			// slice of unsigned integers.
			units := reflect.ValueOf(content)
			enc.bytes = append(enc.bytes, 13)
			enc.Uint(uint64(units.Len()))
			for at := 0; at < units.Len(); at++ {
				enc.Uint(units.Index(at).Uint())
			}
		} else {
			c.describe(enc, reflect.ValueOf(content))
		}
	default:
		return nil, false
	}
	return enc.Done(), true
}

// describeClass describes an instance of a value class of another repository by the in row of its class, or an
// instance of a class of its owner that iterates keys and values as a map of the entries of that iteration (GN-6x).
func (c *Call) describeClass(enc *Writer, value reflect.Value) bool {
	if !value.CanInterface() {
		return false
	}
	switch found := value.Interface().(type) {
	case *json.Value:
		if found == nil {
			return false
		}
		kind, err := found.Kind()
		if err != nil {
			c.raiseIn(enc, err)
			return true
		}
		switch string(kind) {
		case "object":
			c.describeValue(enc, 9, func() (any, error) { return found.Members() }, nil)
		case "array":
			c.describeValue(enc, 8, func() (any, error) { return found.Items() }, nil)
		case "string":
			c.describeValue(enc, 6, func() (any, error) { return found.StringText() }, func() (any, error) { return found.StringUnits() })
		case "number":
			c.describeValue(enc, 5, func() (any, error) { return found.NumberLiteral() }, nil)
		case "boolean":
			c.describeValue(enc, 1, func() (any, error) { return found.BooleanValue() }, nil)
		case "null":
			c.describeValue(enc, 0, nil, nil)
		default:
			c.raiseIn(enc, internalError(fmt.Sprintf("GN-6x: json.Value gives the kind %s, which its in row has no case for", kind)))
		}
		return true
	case *json.OrderedMap:
		if found == nil {
			return false
		}
		entries, err := found.Entries()
		if err != nil {
			c.raiseIn(enc, err)
			return true
		}
		var pairs [][2]reflect.Value
		for key, item := range entries {
			pairs = append(pairs, [2]reflect.Value{reflect.ValueOf(key), reflect.ValueOf(item)})
		}
		enc.bytes = append(enc.bytes, 8)
		enc.Uint(c.hold(held{entries: pairs}))
		enc.Uint(uint64(len(pairs)))
		return true
	}
	return false
}

// describeValue writes node 11: an instance of a value class of another repository, the number of the kind of its in
// case and the handle under which the question read calls the read member of the case (GN-6x).
func (c *Call) describeValue(enc *Writer, kind byte, read, units func() (any, error)) {
	enc.bytes = append(enc.bytes, 11, kind)
	enc.Uint(c.hold(held{read: read, units: units, coded: kind == 11}))
}

// raiseIn writes node 12: the error that a member of the owner of a value class returned, which the call keeps under
// its index, so that the function returns it (GN-6x).
func (c *Call) raiseIn(enc *Writer, err error) {
	c.raised = append(c.raised, err)
	enc.bytes = append(enc.bytes, 12)
	enc.Uint(uint64(c.handle))
	enc.Uint(uint64(len(c.raised) - 1))
}

// describeOwn describes a value of a type of this package: a *KeyedMap[any] as a map of its entries in their order,
// each key an integer, a text or a byte string.
func (c *Call) describeOwn(enc *Writer, value reflect.Value) bool {
	if !value.CanInterface() {
		return false
	}
	switch found := value.Interface().(type) {
	case *KeyedMap[any]:
		var pairs [][2]reflect.Value
		for _, key := range found.Keys() {
			item, _ := found.Get(key)
			var described any = key.text
			switch key.kind {
			case 0:
				described = key.integer
			case 1:
				described = []byte(key.text)
			}
			pairs = append(pairs, [2]reflect.Value{reflect.ValueOf(described), reflect.ValueOf(item)})
		}
		enc.bytes = append(enc.bytes, 8)
		enc.Uint(c.hold(held{entries: pairs}))
		enc.Uint(uint64(len(pairs)))
		return true
	}
	return false
}

// panicked is the panic of Go code that a call ran (GN-15b, GN-6ae), which the call keeps as its error until the call
// of the C ABI returned and the member panics with the same value.
type panicked struct{ value any }

// Error is the text of the value of the panic.
func (p *panicked) Error() string { return fmt.Sprint(p.value) }

// run runs a callback of the call: 0 and the encoded result, 1 and the index of the error that it returned, or 2 and the
// index, the kind and the message of an error that the member recognizes (U-3). A panic of the callback is recovered
// here, because a panic that unwinds through the frames of the static library skips the destructors of the core, its
// guards and its locks: it is the error of the call, whose value the member panics with again (GN-15b).
func (c *Call) run(callback uint64, member uint32, args []byte) (status int32, out []byte) {
	defer func() {
		if value := recover(); value != nil {
			status, out = c.raise(&panicked{value: value})
		}
	}()
	if callback == 0 || callback > uint64(len(c.callbacks)) {
		return c.raise(Malformed())
	}
	enc := NewWriter()
	if err := c.callbacks[callback-1](c, member, readerOf(args), enc); err != nil {
		return c.raise(err)
	}
	return 0, enc.Done()
}

func (c *Call) raise(err error) (int32, []byte) {
	if r, ok := err.(*recognized); ok {
		// U-3, GN-6d: 2, the index of the error, its kind and its message, which the core takes as its kind.
		c.raised = append(c.raised, r.err)
		enc := NewWriter()
		enc.Uint(uint64(len(c.raised) - 1))
		enc.Text(r.kind)
		enc.Text(r.message)
		return 2, enc.Done()
	}
	c.raised = append(c.raised, err)
	enc := NewWriter()
	enc.Uint(uint64(len(c.raised) - 1))
	return 1, enc.Done()
}

// callOf is the call of a handle that the static library gave back.
func callOf(handle uint64) *Call { return cgo.Handle(uintptr(handle)).Value().(*Call) }

// raisedError is the error that a callback of the call returned (U-3). A panic of the callback (GN-15b) is not returned:
// the member panics with its value again, now that the call of the C ABI returned.
func raisedError(call, index uint64) error {
	c := callOf(call)
	if index >= uint64(len(c.raised)) {
		return Malformed()
	}
	if p, ok := c.raised[index].(*panicked); ok {
		panic(p.value)
	}
	return c.raised[index]
}

// give writes bytes into a buffer of the static library, which takes it back.
func give(bytes []byte, result *C.polyspec_crud_ui_generator__buffer) {
	C.polyspec_crud_ui_generator___alloc(C.size_t(len(bytes)), result)
	if len(bytes) > 0 {
		copy(unsafe.Slice((*byte)(unsafe.Pointer(result.ptr)), len(bytes)), bytes)
	}
}

// polyspec_crud_ui_generator___go_callback runs a member of a callback of a call for the static library (U-3).
//
//export polyspec_crud_ui_generator___go_callback
func polyspec_crud_ui_generator___go_callback(call C.uint64_t, callback C.uint64_t, member C.uint32_t, args *C.uint8_t, length C.size_t, result *C.polyspec_crud_ui_generator__buffer) C.int32_t {
	bytes := C.GoBytes(unsafe.Pointer(args), C.int(length))
	status, out := callOf(uint64(call)).run(uint64(callback), uint32(member), bytes)
	give(out, result)
	return C.int32_t(status)
}

// polyspec_crud_ui_generator___go_host describes a child of a Go value of a call for the static library (U-7, B-1).
//
//export polyspec_crud_ui_generator___go_host
func polyspec_crud_ui_generator___go_host(call C.uint64_t, op C.uint32_t, handle C.uint64_t, index C.uint64_t, result *C.polyspec_crud_ui_generator__buffer) C.int32_t {
	out, ok := callOf(uint64(call)).host(uint32(op), uint64(handle), uint64(index))
	give(out, result)
	if !ok {
		return 1
	}
	return 0
}

// polyspec_crud_ui_generator___go_release deletes the cgo.Handle of a func that a Native of the static library held (GN-6u).
//
//export polyspec_crud_ui_generator___go_release
func polyspec_crud_ui_generator___go_release(handle C.uint64_t) {
	cgo.Handle(uintptr(handle)).Delete()
}

// polyspec_crud_ui_generator___go_native gives a new cgo.Handle of the func of a Native, which the decoder of the value deletes (GN-6u).
//
//export polyspec_crud_ui_generator___go_native
func polyspec_crud_ui_generator___go_native(handle C.uint64_t) C.uint64_t {
	return C.uint64_t(cgo.NewHandle(cgo.Handle(uintptr(handle)).Value()))
}

// Writer encodes the arguments of a call: each value in the order of the parameters (B-8).
type Writer struct{ bytes []byte }

// NewWriter is an empty argument buffer.
func NewWriter() *Writer { return &Writer{} }

// Done is the encoded arguments.
func (w *Writer) Done() []byte { return w.bytes }

// Bool encodes a bool as one byte, 0 or 1.
func (w *Writer) Bool(value bool) {
	if value {
		w.bytes = append(w.bytes, 1)
	} else {
		w.bytes = append(w.bytes, 0)
	}
}

// Tag encodes the presence of an optional value.
func (w *Writer) Tag(present bool) { w.Bool(present) }

// Uint encodes a uint64 as eight bytes, little endian.
func (w *Writer) Uint(value uint64) { w.bytes = binary.LittleEndian.AppendUint64(w.bytes, value) }

// Int encodes an int64 as its two's complement.
func (w *Writer) Int(value int64) { w.Uint(uint64(value)) }

// Float encodes a float64 as its IEEE 754 bits.
func (w *Writer) Float(value float64) { w.Uint(math.Float64bits(value)) }

// Len encodes the length of a list.
func (w *Writer) Len(length int) { w.Uint(uint64(length)) }

// Text encodes the bytes of a string with their length; the core judges whether text is UTF-8 (B-8).
func (w *Writer) Text(value string) {
	w.Len(len(value))
	w.bytes = append(w.bytes, value...)
}

// Bytes encodes a byte slice with its length.
func (w *Writer) Bytes(value []byte) {
	w.Len(len(value))
	w.bytes = append(w.bytes, value...)
}

// Reader decodes the result of a call. A result that does not follow the encoding, which only a fault of the
// generated code can make, fails Finish with kind internal.
type Reader struct {
	bytes   []byte
	failed  bool
	problem string
	// err is the error of a function of the owner of a value class of another repository that made a value (GN-6x).
	err error
	// funcs are the funcs of the cgo.Handle list of a buffer that Rust gave, by their indexes (GN-6u).
	funcs []any
}

// NewReader reads an encoded result.
func NewReader(bytes []byte) *Reader { return &Reader{bytes: bytes} }

func (r *Reader) take(count uint64) []byte {
	if r.failed || count > uint64(len(r.bytes)) {
		r.failed = true
		return nil
	}
	head := r.bytes[:count]
	r.bytes = r.bytes[count:]
	return head
}

// Bool decodes a bool.
func (r *Reader) Bool() bool {
	head := r.take(1)
	if r.failed {
		return false
	}
	if head[0] > 1 {
		r.failed = true
	}
	return head[0] == 1
}

// Tag decodes the presence of an optional value.
func (r *Reader) Tag() bool { return r.Bool() }

// Uint decodes a uint64.
func (r *Reader) Uint() uint64 {
	head := r.take(8)
	if r.failed {
		return 0
	}
	return binary.LittleEndian.Uint64(head)
}

// Int decodes an int64.
func (r *Reader) Int() int64 { return int64(r.Uint()) }

// Float decodes a float64.
func (r *Reader) Float() float64 { return math.Float64frombits(r.Uint()) }

// Len decodes the length of a list, which is at most the count of the bytes left.
func (r *Reader) Len() int {
	length := r.Uint()
	if r.failed || length > uint64(len(r.bytes)) {
		r.failed = true
		return 0
	}
	return int(length)
}

// Text decodes a string.
func (r *Reader) Text() string { return string(r.Bytes()) }

// Bytes decodes a byte slice, which it copies.
func (r *Reader) Bytes() []byte {
	head := r.take(r.Uint())
	if r.failed {
		return nil
	}
	return append([]byte{}, head...)
}

// Finish is nil when the result was read whole, and an error of kind internal otherwise.
func (r *Reader) Finish() error {
	if r.err != nil {
		return r.err
	}
	if r.problem != "" {
		return internalError(r.problem)
	}
	if r.failed || len(r.bytes) != 0 {
		return Malformed()
	}
	return nil
}

// Map is the contract type map<T> (T-2): text keys in the order in which they were first set, each once with its
// value, because the core keeps the order of a map and a Go map iterates in a random order.
type Map[T any] struct {
	keys   []string
	values map[string]T
}

// Set sets the value of a key: a new key goes after the others, a key that the map has keeps its place.
func (m *Map[T]) Set(key string, value T) {
	if m.values == nil {
		m.values = map[string]T{}
	}
	if _, ok := m.values[key]; !ok {
		m.keys = append(m.keys, key)
	}
	m.values[key] = value
}

// Get is the value of a key and whether the map has the key.
func (m *Map[T]) Get(key string) (T, bool) {
	if m == nil {
		var zero T
		return zero, false
	}
	value, ok := m.values[key]
	return value, ok
}

// Keys is the keys in their order.
func (m *Map[T]) Keys() []string {
	if m == nil {
		return nil
	}
	return append([]string(nil), m.keys...)
}

// Len is the count of the keys.
func (m *Map[T]) Len() int {
	if m == nil {
		return 0
	}
	return len(m.keys)
}

// Key is a key of the contract type keyed_map<T> (T-2): an integer, a byte string or a text. Keys of different kinds
// are different keys, as IntKey(1), BytesKey([]byte("1")) and TextKey("1").
type Key struct {
	kind    byte
	integer int64
	text    string
}

// IntKey is the integer key of a value.
func IntKey(value int64) Key { return Key{kind: 0, integer: value} }

// BytesKey is the byte string key of a value.
func BytesKey(value []byte) Key { return Key{kind: 1, text: string(value)} }

// TextKey is the text key of a value.
func TextKey(value string) Key { return Key{kind: 2, text: value} }

// Int is the integer of an integer key.
func (k Key) Int() (int64, bool) { return k.integer, k.kind == 0 }

// Bytes is the byte string of a byte string key.
func (k Key) Bytes() ([]byte, bool) {
	if k.kind != 1 {
		return nil, false
	}
	return []byte(k.text), true
}

// Text is the text of a text key.
func (k Key) Text() (string, bool) {
	if k.kind != 2 {
		return "", false
	}
	return k.text, true
}

// KeyedMap is the contract type keyed_map<T> (T-2): keys in the order in which they were first set, each once with
// its value.
type KeyedMap[T any] struct {
	keys   []Key
	values map[Key]T
}

// Set sets the value of a key: a new key goes after the others, a key that the map has keeps its place.
func (m *KeyedMap[T]) Set(key Key, value T) {
	if m.values == nil {
		m.values = map[Key]T{}
	}
	if _, ok := m.values[key]; !ok {
		m.keys = append(m.keys, key)
	}
	m.values[key] = value
}

// Get is the value of a key and whether the map has the key.
func (m *KeyedMap[T]) Get(key Key) (T, bool) {
	if m == nil {
		var zero T
		return zero, false
	}
	value, ok := m.values[key]
	return value, ok
}

// Keys is the keys in their order.
func (m *KeyedMap[T]) Keys() []Key {
	if m == nil {
		return nil
	}
	return append([]Key(nil), m.keys...)
}

// Len is the count of the keys.
func (m *KeyedMap[T]) Len() int {
	if m == nil {
		return 0
	}
	return len(m.keys)
}

// Token is the first parameter of the functions through which a module of the binding reaches a class or a callback
// of another module (GN-15a): only the packages of the Go module can name this internal package, so no other code
// calls them.
type Token struct{}

// Value decodes a value of a value alias (U-7), whose nodes are 0 nil, 1 a bool, 2 an int64, 3 a float64, 4 a string,
// 5 a []byte, 6 a []any, 7 a map[string]any, 8 a container made before, by its index, 9 a *KeyedMap[any], 10 an
// instance of a class by the number of the class and its handle, 11 the func of a Native by the index of its
// cgo.Handle in the list of the buffer, which readerOf deleted (GN-6u), and 255 a value that the out rows give no Go
// form, which fails Finish with kind internal.
func (r *Reader) Value() any {
	return r.ValueWith(nil)
}

// ValueWith decodes a value of a value alias whose out rows make instances of classes (GN-15c): instance makes the
// instance of the class of a number around its handle, and nil for a number that its package does not make.
func (r *Reader) ValueWith(instance func(class uint64, handle uint64) any) any {
	var made []any
	return r.value(&made, instance)
}

func (r *Reader) value(made *[]any, instance func(class uint64, handle uint64) any) any {
	head := r.take(1)
	if r.failed {
		return nil
	}
	switch head[0] {
	case 0:
		return nil
	case 1:
		return r.Bool()
	case 2:
		return r.Int()
	case 3:
		return r.Float()
	case 4:
		return r.Text()
	case 5:
		return r.Bytes()
	case 6:
		items := make([]any, r.Len())
		*made = append(*made, items)
		for at := range items {
			items[at] = r.value(made, instance)
		}
		return items
	case 7:
		entries := map[string]any{}
		*made = append(*made, entries)
		for at, n := 0, r.Len(); at < n; at++ {
			key, ok := r.value(made, instance).(string)
			if !ok {
				r.fail("U-7: a key of a map[string]any that is not a text")
				return nil
			}
			entries[key] = r.value(made, instance)
		}
		return entries
	case 8:
		index := r.Uint()
		if index >= uint64(len(*made)) {
			r.failed = true
			return nil
		}
		return (*made)[index]
	case 9:
		entries := &KeyedMap[any]{}
		*made = append(*made, entries)
		for at, n := 0, r.Len(); at < n; at++ {
			var key Key
			switch found := r.value(made, instance).(type) {
			case int64:
				key = IntKey(found)
			case string:
				key = TextKey(found)
			case []byte:
				key = BytesKey(found)
			default:
				r.fail("U-7: a key of a keyed map that is no integer, byte string or text")
				return nil
			}
			entries.Set(key, r.value(made, instance))
		}
		return entries
	case 10:
		class, handle := r.Uint(), r.Uint()
		if r.failed {
			return nil
		}
		var made any
		if instance != nil {
			made = instance(class, handle)
		}
		if made == nil {
			r.fail(fmt.Sprintf("U-7: an instance of the class %d that the package of the call does not make", class))
		}
		return made
	case 13:
		index := r.Uint()
		if r.failed || index >= uint64(len(r.funcs)) {
			r.failed = true
			return nil
		}
		return r.funcs[index]
	case 11:
		return r.valueClass(made, instance)
	case 255:
		r.fail(r.Text())
		return nil
	}
	r.failed = true
	return nil
}

func (r *Reader) fail(problem string) {
	if r.problem == "" {
		r.problem = problem
	}
	r.failed = true
}

// valueClass makes an instance of a value class of another repository from node 11 of a result (GN-6x): the number of
// the class and of its out row for Go, then the content of the row, on which it calls the owner's function of the row.
// An error of that function is the error of the call.
func (r *Reader) valueClass(made *[]any, instance func(class uint64, handle uint64) any) any {
	class, row := r.Uint(), r.Uint()
	if r.failed {
		return nil
	}
	var value any
	var err error
	switch {
	case class == 0 && row == 0:
		value, err = json.ValueNull()
	case class == 0 && row == 1:
		value, err = json.ValueBoolean(r.Bool())
	case class == 0 && row == 2:
		value, err = json.ValueNumber(r.Text())
	case class == 0 && row == 3:
		value, err = json.ValueString(r.Text())
	case class == 0 && row == 4:
		units := make([]uint64, r.Len())
		for at := range units {
			units[at] = r.Uint()
		}
		value, err = json.ValueFromUnits(units)
	case class == 0 && row == 5:
		items := make([]*json.Value, r.Len())
		for at := range items {
			items[at], _ = r.value(made, instance).(*json.Value)
		}
		value, err = json.ValueArray(items)
	case class == 0 && row == 6:
		entries, failed := json.NewOrderedMap()
		if failed != nil {
			r.raise(failed)
			return nil
		}
		for at, n := 0, r.Len(); at < n; at++ {
			key, _ := r.value(made, instance).(*json.Value)
			item, _ := r.value(made, instance).(*json.Value)
			if _, failed := entries.Insert(key, item); failed != nil {
				r.raise(failed)
				return nil
			}
		}
		value, err = json.ValueObject(entries)
	default:
		r.failed = true
		return nil
	}
	if err != nil {
		r.raise(err)
		return nil
	}
	return value
}

// raise keeps the error of a function of the owner of a value class, which Finish returns (GN-6x).
func (r *Reader) raise(err error) {
	if r.err == nil {
		r.err = err
	}
	r.failed = true
}

// failure is the data of every error type: the message, the kind, the status and the errno of the core (E-7).
type failure struct {
	message   string
	kind      string
	status    int
	hasStatus bool
	errno     int
	hasErrno  bool
}

// Malformed is the error of a result that does not follow the encoding, which only a fault of the generated code
// makes: kind internal.
func Malformed() error {
	return internalError("the encoded result does not follow the encoding of the binding")
}

func internalError(detail string) error {
	return &CRUDUIInternalError{failure{message: fmt.Sprintf("internal error: %s", detail), kind: "internal"}}
}

// finished is the error of a failure whose properties were read whole, or kind internal.
func finished(err error, properties *Reader) error {
	if properties.Finish() != nil {
		return Malformed()
	}
	return err
}

// decodeFailure reads an encoded failure: the category, the message, the kind, the status, the errno, the class of
// the kind with the properties of its unit (E-2, I-3), and the error that a Go callback returned (U-3), which the call
// returns unchanged.
func decodeFailure(r *Reader) error {
	head := r.take(1)
	f := failure{message: r.Text(), kind: r.Text()}
	if r.Tag() {
		f.status, f.hasStatus = int(r.Uint()), true
	}
	if r.Tag() {
		f.errno, f.hasErrno = int(r.Int()), true
	}
	class := r.take(1)
	properties := NewReader(r.Bytes())
	properties.funcs = r.funcs
	var call, index uint64
	present := r.Tag()
	if present {
		call, index = r.Uint(), r.Uint()
	}
	if r.Finish() != nil {
		return Malformed()
	}
	if present {
		return raisedError(call, index)
	}
	category := head[0]
	switch class[0] {
	case 0:
		switch category {
		case 0:
			return finished(&CRUDUIValueError{f}, properties)
		case 1:
			return finished(&CRUDUITypeError{f}, properties)
		case 2:
			return finished(&CRUDUIIoError{f}, properties)
		case 3:
			return finished(&CRUDUIStoreError{f}, properties)
		case 4:
			return finished(&CRUDUIBusyError{f}, properties)
		case 5:
			return finished(&CRUDUIInternalError{f}, properties)
		}
	case 1:
		if category != 0 {
			return Malformed()
		}
		return finished(makeFormError(&CRUDUIValueError{f}, properties), properties)
	}
	return Malformed()
}

// CRUDUIValueError is an error of category value (E-7).
type CRUDUIValueError struct{ failure }

// Error is the message of the failure (B-1).
func (e *CRUDUIValueError) Error() string { return e.message }

// Kind is the kind of the failure (B-4).
func (e *CRUDUIValueError) Kind() string { return e.kind }

// Status is the HTTP status of the kind, when it has one (B-4).
func (e *CRUDUIValueError) Status() (int, bool) { return e.status, e.hasStatus }

// Errno is the OS error number of an I/O failure, when there is one (B-4).
func (e *CRUDUIValueError) Errno() (int, bool) { return e.errno, e.hasErrno }

// CRUDUITypeError is an error of category type (E-7).
type CRUDUITypeError struct{ failure }

// Error is the message of the failure (B-1).
func (e *CRUDUITypeError) Error() string { return e.message }

// Kind is the kind of the failure (B-4).
func (e *CRUDUITypeError) Kind() string { return e.kind }

// Status is the HTTP status of the kind, when it has one (B-4).
func (e *CRUDUITypeError) Status() (int, bool) { return e.status, e.hasStatus }

// Errno is the OS error number of an I/O failure, when there is one (B-4).
func (e *CRUDUITypeError) Errno() (int, bool) { return e.errno, e.hasErrno }

// CRUDUIIoError is an error of category io (E-7).
type CRUDUIIoError struct{ failure }

// Error is the message of the failure (B-1).
func (e *CRUDUIIoError) Error() string { return e.message }

// Kind is the kind of the failure (B-4).
func (e *CRUDUIIoError) Kind() string { return e.kind }

// Status is the HTTP status of the kind, when it has one (B-4).
func (e *CRUDUIIoError) Status() (int, bool) { return e.status, e.hasStatus }

// Errno is the OS error number of an I/O failure, when there is one (B-4).
func (e *CRUDUIIoError) Errno() (int, bool) { return e.errno, e.hasErrno }

