type CRUDUIStoreError struct{ failure }

// Error is the message of the failure (B-1).
func (e *CRUDUIStoreError) Error() string { return e.message }

// Kind is the kind of the failure (B-4).
func (e *CRUDUIStoreError) Kind() string { return e.kind }

// Status is the HTTP status of the kind, when it has one (B-4).
func (e *CRUDUIStoreError) Status() (int, bool) { return e.status, e.hasStatus }

// Errno is the OS error number of an I/O failure, when there is one (B-4).
func (e *CRUDUIStoreError) Errno() (int, bool) { return e.errno, e.hasErrno }

