// FormError is the error unit form_error (E-2): an error of category value,
// which errors.As finds as each of them too.
type FormError struct {
	*CRUDUIValueError
	pAt    string
	pTrace []string
}

// Unwrap is the error of the category, which errors.As reads on.
func (e *FormError) Unwrap() error { return e.CRUDUIValueError }

// At is the property form_error.at (I-3).
func (e *FormError) At() string { return e.pAt }

// Trace is the property form_error.trace (I-3).
func (e *FormError) Trace() []string { return e.pTrace }

func makeFormError(base *CRUDUIValueError, r *Reader) *FormError {
	e := &FormError{CRUDUIValueError: base}
	e.pAt = r.Text()
	e.pTrace = make([]string, r.Len())
	for i0 := range e.pTrace {
		e.pTrace[i0] = r.Text()
	}
	return e
}

// recognized is an error of an error unit that a callback member recognizes (U-3, GN-6d): the core takes its kind and
// its message, and the call keeps the error itself.
type recognized struct {
	err     error
	kind    string
	message string
}

// Error is the message of the error.
func (r *recognized) Error() string { return r.err.Error() }

// Unwrap is the error itself.
func (r *recognized) Unwrap() error { return r.err }

// RecognizeAs is err as an error that the core recognizes when it is a T, an error unit of the owner of a callback unit
// of another repository, and err otherwise (U-3, GN-6s).
func RecognizeAs[T interface {
	error
	Kind() string
}](err error) error {
	var unit T
	if errors.As(err, &unit) {
		return &recognized{err: err, kind: unit.Kind(), message: unit.Error()}
	}
	return err
}

// The static library calls these exports through C (B-8). The initializer takes the value of each, so a call graph
// of the Go code alone, such as that of deadcode, reaches them and what they call (GN-15h).
var _ = [...]any{
	polyspec_crud_ui_generator___go_callback,
	polyspec_crud_ui_generator___go_host,
	polyspec_crud_ui_generator___go_release,
	polyspec_crud_ui_generator___go_native,
}
